JOIN open_tables ot ON ot.creator_id = cu.id AND ot.title = v.title AND ot.start_time = (date_trunc('week', LOCALTIMESTAMP) + make_interval(mins => (v.sm)::int))
JOIN users u ON u.email = v.ue
WHERE (SELECT go FROM seed_run)

RETURNING id
)
